env -u UV_PYTHON uv run --no-sync python - <<'EOF'
import json
from collections import Counter
from pathlib import Path

path = Path("tests/fixtures/claude_code_session.jsonl")
recs = []
bad = 0
for line in path.read_text().splitlines():
    if not line.strip():
        continue
    try:
        recs.append(json.loads(line))
    except json.JSONDecodeError:
        bad += 1

print("total lines parsed:", len(recs), "bad:", bad)
print("record types:", Counter(r.get("type") for r in recs))

assistant_blocks = Counter()
tool_use_names = Counter()
tool_use_ids = {}
for r in recs:
    if r.get("type") == "assistant":
        for b in r["message"]["content"]:
            assistant_blocks[b["type"]] += 1
            if b["type"] == "tool_use":
                tool_use_names[b["name"]] += 1
                tool_use_ids[b["id"]] = b["name"]
print("assistant blocks:", assistant_blocks)
print("tool_use names:", tool_use_names)

user_string = 0
user_text_blocks = 0
user_tool_results = 0
tool_result_ids = []
toolUseResult_count = 0
for r in recs:
    if r.get("type") == "user":
        c = r["message"]["content"]
        if isinstance(c, str):
            user_string += 1
        else:
            for b in c:
                if b["type"] == "text":
                    user_text_blocks += 1
                elif b["type"] == "tool_result":
                    user_tool_results += 1
                    tool_result_ids.append(b["tool_use_id"])
        if "toolUseResult" in r:
            toolUseResult_count += 1
print("user string content:", user_string, "user text blocks:", user_text_blocks, "tool_result blocks:", user_tool_results)
print("toolUseResult records:", toolUseResult_count)

# which tools do tool_results pair to?
paired = Counter(tool_use_ids.get(i, "UNKNOWN") for i in tool_result_ids)
print("tool_result paired tools:", paired)
# unmatched tool_use ids?
unmatched = [i for i in tool_use_ids if i not in set(tool_result_ids)]
print("tool_use without result:", [(i, tool_use_ids[i]) for i in unmatched])

# first record with session info
for r in recs:
    if "sessionId" in r:
        print("first sessionId rec:", {k: r.get(k) for k in ("type","sessionId","cwd","gitBranch","version")})
        break

# first user prompt
for r in recs:
    if r.get("type") == "user":
        c = r["message"]["content"]
        if isinstance(c, str):
            print("first user prompt (start):", repr(c[:120]))
            break
        texts = [b["text"] for b in c if b["type"] == "text"]
        if texts:
            print("first user prompt block (start):", repr(texts[0][:120]))
            break

# sample a queue-operation, attachment, toolUseResult structure
for t in ("queue-operation", "attachment", "system", "mode", "ai-title", "last-prompt"):
    for r in recs:
        if r.get("type") == t:
            print(t, "keys:", sorted(r.keys()))
            break

# sample toolUseResult for Bash and Read
shown = set()
for r in recs:
    tur = r.get("toolUseResult")
    if tur is None or r.get("type") != "user":
        continue
    c = r["message"]["content"]
    if isinstance(c, list):
        for b in c:
            if b["type"] == "tool_result":
                name = tool_use_ids.get(b["tool_use_id"])
                if name not in shown:
                    shown.add(name)
                    print(f"toolUseResult for {name}: type={type(tur).__name__}", end=" ")
                    if isinstance(tur, dict):
                        print("keys:", sorted(tur.keys())[:12])
                    else:
                        print("value (start):", repr(str(tur)[:80]))
EOF

env -u UV_PYTHON uv run --no-sync python - <<'EOF'
import json
from pathlib import Path

recs = [json.loads(line) for line in Path("tests/fixtures/claude_code_session.jsonl").read_text().splitlines() if line.strip()]

# first non-None value per metadata source field
for key in ("sessionId", "cwd", "gitBranch", "version"):
    for i, r in enumerate(recs):
        v = r.get(key)
        if v is not None:
            print(key, "-> rec", i, r.get("type"), repr(v)[:80])
            break
    else:
        print(key, "-> NEVER non-None")

# first user prompt
for r in recs:
    if r.get("type") == "user" and isinstance(r["message"]["content"], str):
        print("first prompt len:", len(r["message"]["content"]))
        print("first prompt start:", repr(r["message"]["content"][:60]))
        break

# one Bash pair: command + toolUseResult stdout/stderr
tool_use = {}
for r in recs:
    if r.get("type") == "assistant":
        for b in r["message"]["content"]:
            if b["type"] == "tool_use" and b["name"] == "Bash":
                tool_use[b["id"]] = b["input"].get("command")
done = False
for r in recs:
    if done: break
    if r.get("type") == "user" and isinstance(r["message"]["content"], list):
        for b in r["message"]["content"]:
            if b["type"] == "tool_result" and b["tool_use_id"] in tool_use:
                tur = r.get("toolUseResult")
                print("bash cmd:", repr(tool_use[b['tool_use_id']])[:80])
                print("tur stdout:", repr(tur.get("stdout"))[:80])
                print("tur stderr:", repr(tur.get("stderr"))[:80])
                print("block content type:", type(b.get("content")).__name__)
                done = True
                break

# Read tool_result block content shape + is_error presence
done = False
for r in recs:
    if done: break
    if r.get("type") == "user" and isinstance(r["message"]["content"], list):
        for b in r["message"]["content"]:
            if b["type"] == "tool_result" and b["tool_use_id"] not in tool_use:
                print("read result content type:", type(b.get("content")).__name__, "is_error" in b)
                if isinstance(b.get("content"), list):
                    print("  list item types:", [x.get("type") for x in b["content"]])
                done = True
                break
EOF

env -u UV_PYTHON uv run --no-sync python - <<'EOF'
import json
from pathlib import Path
recs = [json.loads(l) for l in Path("tests/fixtures/claude_code_session.jsonl").read_text().splitlines() if l.strip()]
bash_ids = {}
for r in recs:
    if r.get("type") == "assistant":
        for b in r["message"]["content"]:
            if b["type"] == "tool_use" and b["name"] == "Bash":
                bash_ids[b["id"]] = b["input"].get("command", "")[:50]
empty = nonempty = 0
for r in recs:
    if r.get("type") == "user" and isinstance(r["message"]["content"], list):
        for b in r["message"]["content"]:
            if b.get("type") == "tool_result" and b["tool_use_id"] in bash_ids:
                tur = r.get("toolUseResult") or {}
                out = (tur.get("stdout") or "") + (tur.get("stderr") or "")
                if out.strip():
                    nonempty += 1
                else:
                    empty += 1
                    print("EMPTY:", repr(bash_ids[b["tool_use_id"]]))
print("nonempty:", nonempty, "empty:", empty)
EOF
